<?php
declare(strict_types=1);
namespace App\Service;
final class SimplePdf{
 public static function send(string $title,array $lines,string $filename):never{$text=array_merge([$title,''],array_map(static fn($v)=>is_scalar($v)?(string)$v:json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$lines));$stream="BT /F1 11 Tf 45 800 Td 14 TL\n";foreach(array_slice($text,0,52) as $line){$line=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],substr($line,0,130));$stream.="({$line}) Tj T*\n";}$stream.="ET";$objects=[];$objects[]='1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj';$objects[]='2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj';$objects[]='3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >> endobj';$objects[]='4 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj';$objects[]="5 0 obj << /Length ".strlen($stream)." >> stream\n{$stream}\nendstream endobj";$pdf="%PDF-1.4\n";$offset=[0];foreach($objects as $o){$offset[]=strlen($pdf);$pdf.=$o."\n";}$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";for($i=1;$i<=5;$i++)$pdf.=sprintf('%010d 00000 n ',$offset[$i])."\n";$pdf.="trailer << /Size 6 /Root 1 0 R >>\nstartxref\n{$xref}\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',$filename).'"');header('Content-Length: '.strlen($pdf));echo$pdf;exit;}
}
